#!/usr/bin/env python3
"""Apply WP-0013: ADR-0015, Team format schema, WP-0013 claim, WP-0223 update."""
import base64
import os

REPO = "."
FILES = {
    'program/decisions/ADR-0015-online-demo-architecture-for-the-playground.md': "",
    'program/spec/schemas/team-format.schema.json': "",
    'program/work/P0/WP-0013-online-demo-architecture-decision-for-the-playground.md': "",
    'program/work/P2/WP-0223-playground-in-the-online-demo.md': "",
}

def main():
    for path, b64 in FILES.items():
        full = os.path.join(REPO, path)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        with open(full, "w", encoding="utf-8") as f:
            f.write(base64.b64decode(b64).decode("utf-8"))
        print("wrote", path)

if __name__ == "__main__":
    main()
